-- EvalOtter seed data — generated by scripts/seed/generate-sql.ts
-- Equivalent to `npm run seed`. Idempotent: safe to re-run.
-- 29 assessments from scripts/seed/data/*.json
-- Run AFTER the schema migrations (supabase/combined_migrations.sql).
-- cognitive-flexibility-index — file 5 of 29. Self-contained: its
-- category, its own questions, then the assessment itself.
-- Safe to re-run on its own.

begin;
insert into assessment_categories (key, label, icon, "order") values ('cognitive', 'Cognitive', 'brain', 1)
  on conflict (key) do update set label = excluded.label, icon = excluded.icon, "order" = excluded."order";

insert into questions (external_key, question_type, question_text, instructions, media, correct_answer, score_config, difficulty, category, tags, time_limit_seconds, required) values ('cfi-wcst-01', ('custom_interactive')::question_type, 'Sort each card under the key card you believe it matches.', NULL, ('[]')::jsonb, NULL, (convert_from(decode('W3siZGltZW5zaW9uS2V5IjoiY29nbml0aXZlLWZsZXhpYmlsaXR5IiwicG9pbnRzIjoxMH1d', 'base64'), 'UTF8'))::jsonb, ('medium')::assessment_difficulty, 'cognitive-flexibility-index', ARRAY['wcst']::text[], NULL, true)
  on conflict (external_key) do update set question_type = excluded.question_type, question_text = excluded.question_text, instructions = excluded.instructions, media = excluded.media, correct_answer = excluded.correct_answer, score_config = excluded.score_config, difficulty = excluded.difficulty, category = excluded.category, tags = excluded.tags, time_limit_seconds = excluded.time_limit_seconds, required = excluded.required;
delete from question_options where question_id = (select id from questions where external_key = 'cfi-wcst-01');

-- cognitive-flexibility-index (cognitive-flexibility-index.json)
insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('cognitive-flexibility-index', 'Cognitive Flexibility Index', 'Task-switching and rule-reversal exercises measuring how easily you adapt when the rules change mid-task.', convert_from(decode('', 'base64'), 'UTF8'), 'shuffle', (select id from assessment_categories where key = 'cognitive'), ('hybrid')::assessment_engine_type, ('medium')::assessment_difficulty, 12, 1, false, ('free')::assessment_access, ('published')::assessment_status)
  on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, long_description = excluded.long_description, icon = excluded.icon, category_id = excluded.category_id, engine_type = excluded.engine_type, difficulty = excluded.difficulty, estimated_duration_minutes = excluded.estimated_duration_minutes, question_count = excluded.question_count, featured = excluded.featured, access = excluded.access, status = excluded.status;
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'cognitive-flexibility', 'Cognitive Flexibility', 'Set-shifting ability — finding a hidden sorting rule and adapting when it changes, measured live via category completions and resistance to perseverative errors.', true, 'logical', 1)
  on conflict (assessment_id, key) do update set label = excluded.label, description = excluded.description, contributes_to_brain_profile = excluded.contributes_to_brain_profile, brain_profile_dimension_key = excluded.brain_profile_dimension_key, "order" = excluded."order";
delete from result_ranges where assessment_id = (select id from assessments where slug = 'cognitive-flexibility-index');
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'overall', 0, 30, 'Developing', 'Finding the hidden rule (and re-finding it after a shift) was difficult this round — a very common pattern, since WCST is specifically designed to be hard to game.', ARRAY['After a run of wrong answers, deliberately try a different attribute (color, then shape, then count) rather than repeating your last guess', convert_from(decode('V2hlbiB5b3Ugbm90aWNlIHNldmVyYWwgc29ydHMgaW4gYSByb3cgZ29pbmcgd3JvbmcgYWZ0ZXIgcHJldmlvdXNseSBkb2luZyB3ZWxsLCB0aGF0J3MgdGhlIHNpZ25hbCB0aGUgcnVsZSBqdXN0IHNoaWZ0ZWQg4oCUIHRyZWF0IGl0IGFzIG5ldyBpbmZvcm1hdGlvbiwgbm90IGJhZCBsdWNr', 'base64'), 'UTF8'), 'Retake later — this measure is sensitive to mental fatigue and rushing']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'overall', 31, 50, 'Average', 'Found the rule reliably at least once, but shifts cost several extra wrong sorts before adapting.', ARRAY['Practice noticing a shift faster — 2-3 wrong sorts in a row after previously being consistent is a strong shift signal', 'Consciously test a *different* attribute after a few wrong sorts rather than persisting with what worked before']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'overall', 51, 70, 'Strong', 'Adapts to rule shifts reasonably quickly, with occasional perseveration right after a shift.', ARRAY['Push for faster shift detection — aim to catch a shift within 1-2 wrong sorts', 'Notice which of the three rule types (color/shape/number) you personally find hardest to switch to']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'overall', 71, 85, 'Very Strong', 'Detects rule shifts quickly and rarely perseverates on an outdated rule.', ARRAY['This is a strong, genuine set-shifting result — a real asset in fast-changing work environments', convert_from(decode('Tm90aWNlIGhvdyB0aGlzIGNvbXBhcmVzIHRvIHlvdXIgRXhlY3V0aXZlIEZ1bmN0aW9uIFByb2ZpbGluZyAnU2hpZnQnIHNjYWxlLCBpZiB5b3UndmUgdGFrZW4gaXQ=', 'base64'), 'UTF8')]::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'overall', 86, 100, 'Exceptional', 'Near-optimal set-shifting — categories completed quickly with minimal perseverative errors.', ARRAY[convert_from(decode('VGhpcyBpcyBhbiBlbGl0ZSBjb2duaXRpdmUtZmxleGliaWxpdHkgcmVzdWx0IG9uIG9uZSBvZiBuZXVyb3BzeWNob2xvZ3kncyBtb3N0IGVzdGFibGlzaGVkIG1lYXN1cmVz', 'base64'), 'UTF8'), 'Consider how this shows up as an advantage in ambiguous or frequently-changing work']::text[], NULL, 5);
delete from brain_profile_contribution_rules where assessment_id = (select id from assessments where slug = 'cognitive-flexibility-index');
insert into brain_profile_contribution_rules (assessment_id, source_dimension_key, target_brain_profile_dimension_key, weight) values ((select id from assessments where slug = 'cognitive-flexibility-index'), 'cognitive-flexibility', 'logical', 0.5);
insert into assessment_versions (assessment_id, version_number, status, settings, published_at)
  select a.id, coalesce((select max(v.version_number) from assessment_versions v where v.assessment_id = a.id), 0) + 1, 'published'::assessment_status, (convert_from(decode('', 'base64'), 'UTF8'))::jsonb, now()
  from assessments a where a.slug = 'cognitive-flexibility-index';
update assessments set current_version_id = (select v.id from assessment_versions v where v.assessment_id = assessments.id order by v.version_number desc limit 1) where slug = 'cognitive-flexibility-index';
insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values ((select current_version_id from assessments where slug = 'cognitive-flexibility-index'), 'Card Sorting', 'Sort cards under the four key cards by an unstated, shifting rule.', convert_from(decode('V2F0Y2ggdGhlIGZlZWRiYWNrIGFmdGVyIGVhY2ggc29ydCDigJQgdGhhdCdzIHRoZSBvbmx5IHdheSB0byBmaW5kIChhbmQgcmUtZmluZCkgdGhlIHJ1bGUu', 'base64'), 'UTF8'), NULL, false, 1, 1);
insert into scoring_rules (assessment_version_id, dimension_key, formula, section_weights, normalization, penalty_per_incorrect) values ((select current_version_id from assessments where slug = 'cognitive-flexibility-index'), 'cognitive-flexibility', ('sum')::scoring_formula, NULL, (convert_from(decode('eyJtaW4iOjAsIm1heCI6MTB9', 'base64'), 'UTF8'))::jsonb, NULL);
insert into assessment_questions (assessment_version_id, section_id, question_id, "order", weight) values
  ((select current_version_id from assessments where slug = 'cognitive-flexibility-index'), (select id from assessment_sections where assessment_version_id = (select current_version_id from assessments where slug = 'cognitive-flexibility-index') and name = 'Card Sorting'), (select id from questions where external_key = 'cfi-wcst-01'), 1, 1);
commit;
